INSERT INTO feature VALUES('store-facade','storage','One store over both planes and named roots',NULL,'implemented','ordinary',NULL,'One `Store` opens a directory holding the value plane''s chunks, the record plane''s nodes and a record tree of named roots, each object a file named by its digest. A value commits under the store''s profile and its own codec to a pointer, a digest and an offset, that reads back in any process opening the same directory; an object changed on disk is refused by the plane holding it against its digest; and a root one store sets is kept by another setting its own over the same directory. The puts take `&self`, so threads share one store with no lock. Each thread stages its objects in a shard of its own, and one rename an object unions the shard into the plane before the put returns. One register, which the store''s opener owns, names the roots: other threads hand it their namings through a channel, and readers load the snapshot it publishes with no lock. `gandr check` and `gandr lock` open it under the XDG data home, the lock records each dependency''s identity by a pointer into it, and `gandr check` commits each package whose sources settle as its export, every kernel artifact the walk admitted under its sources'' paths, named by `export/<package address>`. Once every export of the run is committed, a dependent''s check reads each path dependency''s export by that root and replays each of its artifacts alone through the kernel; a root naming nothing is noted, and an export the store cannot read back or the kernel refuses faults the run.','storage-store surface-dispatcher surface-driver','crates/storage-store/tests/store.rs crates/surface-dispatcher/tests/package.rs::a_pointer_the_store_cannot_answer_leaves_the_dependent_unaddressed_3157 crates/surface-driver/tests/cli.rs::a_package_s_lock_points_into_the_store_the_run_opens_3157 crates/surface-dispatcher/tests/package.rs::a_package_s_export_holds_what_its_check_admitted_3225 crates/surface-driver/tests/cli.rs::a_checked_package_s_export_is_named_by_its_address_3225 crates/surface-dispatcher/tests/package.rs::a_dependency_s_export_is_re_admitted_through_the_kernel_3285 crates/surface-driver/tests/cli.rs::a_dependent_re_admits_its_dependency_s_export_3285',NULL,'#2765 #2799 #3225 #3285');
